OVERTIME.conversion:
const employment = ctx.subject.employment;
const terms = employment.terms;
const facts = get(employment, 'employee_extension_data', {});
const partTime = get(employment, 'engagement', 'EMPLOYEE') === 'PART_TIME';
const normal = Number(
	get(
		terms,
		'normal_hours_per_day',
		partTime
			? ctx.lookup.part_time_hours_factor * 8
			: 8
	)
);
const full = partTime
	? Number(
			get(facts, 'comparable_full_time_hours_per_day', 8)
		)
	: normal;
const tier = Math.max(0, full - normal);
const orpHour = ctx.hour_rate;
const days = get(ctx, 'work.days', []);
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const ordinary = days
	.filter((day) => ['WORK', 'OFF'].includes(get(day, 'day_type', 'WORK')) && !holiday(day))
	.toSorted((a, b) => {
		const left = String(get(a, 'date', ''));
		const right = String(get(b, 'date', ''));
		if (left < right) return -1;
		return left > right ? 1 : 0;
	});
// The company prices an overtime hour to the sen before it multiplies the hours: the premium rate, rounded.
const band = (premium) => round(premium * orpHour, ctx.lookup.minor_unit, 'HALF_UP');
// all hours on an off day are overtime at the standard premium; a rest day has its own bands
const hoursOf = (day) =>
	Math.max(0, Number(get(day, get(day, 'day_type', 'WORK') === 'OFF' ? 'worked_hours' : 'overtime_hours', 0)));
if (partTime)
	return sum(
		ordinary.map((day) => {
			const hours = hoursOf(day);
			return (
				Math.min(hours, tier) * band(ctx.lookup.part_time_premium) +
				Math.max(0, hours - tier) * band(ctx.lookup.standard_premium)
			);
		})
	);
// each calendar month's hours are totalled, priced and rounded to the minor unit, then the months added: an hour
// is priced in the month it was worked
const months = ordinary
	.map((day) => String(get(day, 'date', '')).slice(0, 7))
	.filter((month, index, all) => all.indexOf(month) === index);
return sum(
	months.map((month) =>
		round(
			sum(ordinary.filter((day) => String(get(day, 'date', '')).slice(0, 7) === month).map(hoursOf)) *
				band(ctx.lookup.standard_premium),
			ctx.lookup.minor_unit,
			'HALF_UP'
		)
	)
);

