const midpoint = w >= ctx.lookup.salary_ceiling ? ctx.lookup.highest_midpoint : round(w, ctx.lookup.hundred_units, 'UP') - ctx.lookup.midpoint_offset;
return midpoint * ctx.lookup.rate;
};
return Math.max(0, charge(Math.min(ctx.subtotals.ORDINARY_WAGES + before('ORDINARY_WAGES'), ctx.lookup.salary_ceiling)) - before('EIS.employer'));

PCB.employee_amount:
const employment = ctx.subject.employment;
const elections = get(employment, 'employee_extension_data.statutory.PCB', {});
const residency = get(employment, 'terms.residency_status', '');
const declared = get(elections, 'tax_residency', '');
const resident =
	declared === 'NON_RESIDENT' ? false
	: declared === 'RESIDENT' ? true
	: residency === 'CITIZEN' || residency === 'PERMANENT_RESIDENT';
// D note, ITA s.25(1): taxed when received, so the pay date decides the month and year.
const period = String(
	get(ctx.run, 'pay_date', '') || get(ctx.run, 'period', '') || get(ctx.run, 'salary_coverage.from', '')
);
const offCycle = get(ctx.run, 'kind', '') === 'OFF_CYCLE';
const months = get(ctx, 'balances.month', {});
// MTD is a month's: a payroll that pays the month in two halves reckons the month to date. What the first half paid
// and withheld counts as this month's, not as earlier months'.
const halves = !offCycle && get(ctx.subject.employer, 'payment_schedule.frequency', '') === 'SEMI_MONTHLY';
const held = (code) => {
	const key = period.slice(0, 7) + '.' + code;
	return halves && Object.hasOwn(months, key) ? Number(months[key]) : 0;
};
const moved = (value, by) => (halves ? round(Number(value) + by, ctx.lookup.minor_unit, 'HALF_UP') : value);
const run = ctx.subtotals;
const now = Object.fromEntries(Object.keys(run).map((code) => [code, moved(get(run, code, 0), held(code))]));
const paid = get(ctx, 'balances.ytd', {});
const ytd = Object.fromEntries(Object.keys(paid).map((code) => [code, moved(paid[code], -held(code))]));
const contributed = get(ctx, 'balances.statutory_contribution', {});
const running = Object.fromEntries(
	Object.keys(now).map((code) => [code, Number(get(now, code, 0)) + Number(get(ytd, code, 0))])
);
// A pay class is the step between two checkpoints, in the month or over the tax year.
const step = (totals, to, from) =>
	Object.hasOwn(totals, to) && Object.hasOwn(totals, from) ? Number(totals[to]) - Number(totals[from]) : 0;
const meal = (totals) => step(totals, 'EXEMPT_ALLOWANCES', 'REGULAR_PAY');
const childcare = (totals) => step(totals, 'CHILDCARE', 'EXEMPT_ALLOWANCES');
const arrears = (totals) => step(totals, 'WAGE_ARREARS', 'CHILDCARE');
const irregular = (totals) => step(totals, 'IRREGULAR_COMMISSION', 'COMMISSION');
const excellence = (totals) => step(totals, 'AWARDS', 'IRREGULAR_COMMISSION');
const longService = (totals) => step(totals, 'LONG_SERVICE', 'AWARDS');
const incentive = (totals) => step(totals, 'INCENTIVE_OT', 'LONG_SERVICE');
const lump = (totals) => step(totals, 'ADDITIONAL_WAGES', 'ORDINARY_WAGES');
const compensation = (totals) => step(totals, 'SEPARATION_PAY', 'ADDITIONAL_WAGES');
const travel = (totals) => step(totals, 'OFFICIAL_TRAVEL', 'SEPARATION_PAY');
const hired = get(employment, 'service_started_on', get(employment, 'effective_range.from', ''));
const lastDay = () => {
	const left = get(employment, 'effective_range.to', null);
	return left !== null && left < ctx.as_of ? left : ctx.as_of;
};
// ITA Sch.6 para 25C: a long service award counts after more than ten years with the employer.
const longServed =
	longService(running) > 0 && add_years(hired, ctx.lookup.long_service_years) < lastDay();
const awards = (totals) => excellence(totals) + (longServed ? longService(totals) : 0);
// Para 15(1)(b): RM10,000 for each completed year of service.
const compensationCap =
	compensation(running) > 0
		? ctx.lookup.compensation_exempt_per_year *
			Math.floor(calendar_completed_months(hired, lastDay()) / 12)
		: 0;
// MTD E(9), PR 5/2019 para 7.5: none of these for an employee who controls the employer.
const relief =
	get(employment, 'employee_extension_data.controls_employer', false) === true ? 0 : 1;
const exemptPart = (part, cap) => relief * Math.min(part, cap);
const exemptIn = (totals) =>
	relief * meal(totals) +
	exemptPart(childcare(totals), ctx.lookup.childcare_exempt) +
	exemptPart(travel(totals), ctx.lookup.travel_exempt) +
	exemptPart(awards(totals), ctx.lookup.award_exempt) +
	Math.min(compensation(totals), compensationCap);
// An annual limit falls on the year's total, so the month is exempt by what the total adds.
const exemptNow = (part, cap) => exemptPart(part(running), cap) - exemptPart(part(ytd), cap);
// MTD D(1): normal pay recurs. D(2): one-off pay, arrears and final settlements enter P once.
const ordinary = Math.max(
	0,
	Number(get(now, 'ORDINARY_WAGES', 0)) - incentive(now) -
		arrears(now) -
		irregular(now) -
		excellence(now) -
		longService(now) -
		relief * meal(now) -
		exemptNow(childcare, ctx.lookup.childcare_exempt) +
		travel(now) -
		exemptNow(travel, ctx.lookup.travel_exempt)
);
// an incentive is additional remuneration: taxed in the month it is paid, not spread over the year
const bonus = Math.max(
	0,
	lump(now) +
		incentive(now) +
		arrears(now) +
		irregular(now) +
		excellence(now) +
		longService(now) -
		exemptNow(awards, ctx.lookup.award_exempt) +
		compensation(now) -
		(Math.min(compensation(running), compensationCap) -
			Math.min(compensation(ytd), compensationCap)) +
		step(now, 'FINAL_PAY', 'OFFICIAL_TRAVEL')
);
const total = ordinary + bonus;
if (!resident) {
	const amount = round(total * ctx.lookup.nonresident_rate, ctx.lookup.five_minor_units, 'UP');
	return Math.max(0, (amount < ctx.lookup.minimum ? 0 : amount) - held('PCB.employee'));
}
const year = period.slice(0, 4);
const month = Number(period.slice(5, 7));
const remaining = month >= 1 && month <= 12 ? 13 - month : 12;
const subsequent = remaining - 1;
// D(2): an off-cycle run pays one-offs, so the year still projects on the contract's month, and this month's
// normal pay counts once: in Y once the on-cycle run has paid it, in Y1 until then. Someone leaving earns no more months.
const leaving = get(employment, 'effective_range.to', null);
// The first half stands for the month: twice its normal pay, and half the month's MTD on it. The second half settles
// the month on what it paid. Someone whose last day is in the first half has no second.
const coverage = get(ctx.run, 'salary_coverage', {});
const share =
	halves &&
	Number(String(get(coverage, 'to', '')).slice(8, 10)) <= 15 &&
	!(leaving !== null && leaving <= get(coverage, 'to', ''))
		? 2
		: 1;
const normal =
	!offCycle ? ordinary * share
	: leaving !== null && leaving <= ctx.as_of ? 0
	: ctx.month_wage;
const paidBasic = period.slice(0, 7) + '.BASIC';
const thisMonth =
	offCycle && Object.hasOwn(months, paidBasic) && Number(months[paidBasic]) > 0 ? 0 : 1;
// MTD Specification 2026 E(10): Form TP3 figures from earlier employers this year enter Y, K, X, Z and LP.
const tp3 = (field) =>
	String(get(elections, 'tp3_year', '')) === year ? Number(get(elections, field, 0)) : 0;
const priorGross =
	Number(get(ytd, 'FINAL_PAY', 0)) - exemptIn(ytd) + tp3('tp3_prior_remuneration');
const priorScheme = (code) =>
	moved(
		Object.hasOwn(contributed, code + '.employee') ? Number(contributed[code + '.employee']) : 0,
		-held(code + '.employee')
	);
const priorEpf = Math.min(
	ctx.lookup.epf_relief_cap,
	priorScheme('EPF') + priorScheme('EPF_PR') + priorScheme('EPF_NON_CITIZEN') + tp3('tp3_prior_epf')
);
const priorTax = priorScheme('PCB') + tp3('tp3_prior_mtd');
// Z: zakat and rebates of earlier months reduce the year's tax for good; ZAKAT is the payroll deduction.
const priorZakat =
	Number(get(elections, 'tp1_zakat_prior', 0)) +
	tp3('tp3_prior_zakat') +
	step(ytd, 'FINAL_PAY', 'ZAKAT');
const employee = (code) =>
	moved(Object.hasOwn(ctx.statutory, code) ? ctx.statutory[code].employee : 0, held(code + '.employee'));
const extra =
	get(elections, 'socso_eis_relief', false) === true
		? Math.min(
				ctx.lookup.socso_eis_relief_cap,
				priorScheme('SOCSO') +
					priorScheme('EIS') +
					priorScheme('SKBBK') +
					employee('SOCSO') +
					employee('EIS') +
					employee('SKBBK')
			)
		: 0;
const children =
	ctx.lookup.child_reliefs.under_18_or_studying *
		Number(get(elections, 'children_under_18_or_studying', 0)) +
	ctx.lookup.child_reliefs.under_18_or_studying_half *
		Number(get(elections, 'children_under_18_or_studying_half', 0)) +
	ctx.lookup.child_reliefs.tertiary_or_disabled *
		Number(get(elections, 'children_tertiary_or_disabled', 0)) +
	ctx.lookup.child_reliefs.tertiary_or_disabled_half *
		Number(get(elections, 'children_tertiary_or_disabled_half', 0)) +
	ctx.lookup.child_reliefs.disabled_tertiary *
		Number(get(elections, 'children_disabled_tertiary', 0)) +
	ctx.lookup.child_reliefs.disabled_tertiary_half *
		Number(get(elections, 'children_disabled_tertiary_half', 0));
const reliefs =
	ctx.lookup.personal_relief +
	(get(employment, 'employee_extension_data.disabled', false) === true
		? ctx.lookup.employee_disabled_relief
		: 0) +
	(get(employment, 'family', []).some((member) => member.relation === 'SPOUSE' && get(member, 'has_income', null) === false) ? ctx.lookup.spouse_relief : 0) +
	(get(employment, 'family', []).some((member) => member.relation === 'SPOUSE' && get(member, 'disabled', false) === true && get(member, 'has_income', null) === false) ? ctx.lookup.spouse_disabled_relief : 0) +
	children;
const tp1 =
	Number(get(elections, 'tp1_accumulated_deductions', 0)) +
	Number(get(elections, 'tp1_monthly_deductions', 0)) +
	tp3('tp3_prior_deductions') +
	extra;
const currentEpf = employee('EPF') + employee('EPF_PR') + employee('EPF_NON_CITIZEN');
const declaredNormal = Number(get(elections, 'pcb_epf_normal_month', 0));
// E(13): EPF on exempt pay is K1, EPF on one-off pay is Kt.
const epfWages = lump(now) + Number(get(now, 'AWARDS', 0));
const epfOneOff = lump(now) + arrears(now) + irregular(now) + excellence(now);
const normalEpf =
	offCycle ?
		Math.min(
			normal,
			declaredNormal > 0 ? declaredNormal
			: epfWages > 0 ? (currentEpf * normal) / epfWages
			: 0
		)
	: bonus <= 0 || epfWages <= 0 ? currentEpf
	: declaredNormal > 0 ? Math.min(declaredNormal, currentEpf)
	: (currentEpf * (epfWages - epfOneOff)) / epfWages;
const room = ctx.lookup.epf_relief_cap - priorEpf;
const k1 = Math.min(normalEpf * share, room);
const kNow = k1 * thisMonth;
const kt = Math.min(offCycle ? currentEpf : currentEpf - normalEpf, room - kNow);
// E(1) and the worked examples: K2 is cut to the sen (RM3,395 / 11 = 308.63).
const k2 = (left) =>
	subsequent > 0
		? Math.min(round(left / subsequent, ctx.lookup.minor_unit, 'TRUNCATE'), k1)
		: 0;
const k2Normal = k2(room - kNow);
const k2Total = k2(room - kNow - kt);
const base = priorGross - priorEpf - reliefs - tp1 + (normal - k1) * thisMonth;
const normalP = Math.max(0, base + (normal - k2Normal) * subsequent);
const totalP = Math.max(0, base + (normal - k2Total) * subsequent + bonus - kt);
const taxOn = (p) =>
	Math.max(
		0,
		ladder(p, ctx.lookup.tax_bands) -
			(p <= ctx.lookup.rebate_threshold
				? ctx.lookup.rebate *
					(get(employment, 'family', []).some((member) => member.relation === 'SPOUSE' && get(member, 'has_income', null) === false) ? 2 : 1)
				: 0)
	);
// E(1), E(3): each MTD is cut to the sen, and normal and additional MTD each fall away below RM10.
const mtd = (amount) => {
	const cut = round(amount, ctx.lookup.minor_unit, 'TRUNCATE');
	return cut < ctx.lookup.minimum ? 0 : cut;
};
// E(2): the amount deducted is rounded up to 5 sen, once.
const deducted = (amount) => round(Math.max(0, amount), ctx.lookup.five_minor_units, 'UP');
const left = subsequent + thisMonth;
const normalMtd = left > 0 ? mtd(Math.max(0, taxOn(normalP) - priorTax - priorZakat) / left) : 0;
const additional =
	bonus > 0
		? mtd(Math.max(0, taxOn(totalP) - priorTax - priorZakat - normalMtd * left))
		: 0;
const zakat = Number(get(elections, 'tp1_zakat_current', 0)) + step(now, 'FINAL_PAY', 'ZAKAT');
return offCycle
	? deducted(additional)
	: Math.max(
			0,
			deducted(round(normalMtd / share, ctx.lookup.minor_unit, 'TRUNCATE') + additional - zakat) -
				held('PCB.employee')
		);

HRDF.eligibility:
const employment = ctx.subject.employment;
// Act 612 s.2: "pekerja" leaves out a domestic servant and "upah" (f) an apprentice's allowance.
if (['PAYEE', 'PART_TIME', 'APPRENTICE'].includes(get(employment, 'engagement', ''))) return false;
if (get(employment, 'terms.statutory_work_category', '') === 'DOMESTIC') return false;
if (get(employment, 'terms.residency_status', '') !== 'CITIZEN') return false;
const employer = ctx.subject.employer;
if (get(employer, 'entity_extension_data.hrd_scope', '') === 'OUT_OF_SCOPE') return false;
if (ctx.lookup.education_schedule_exempt === true) {
 const schedule = get(employer, 'entity_extension_data.hrd_education_schedule_code', 'NONE');
 if (schedule !== '' && schedule !== 'NONE') return false;
}
return true;

HRDF.employer_amount:
const employer = ctx.subject.employer;
const registration = get(employer, 'entity_extension_data.hrd_registration_class', 'COMPULSORY');
const rate =
	registration === 'OPTIONAL' ? ctx.lookup.optional_rate
	: registration === 'COMPULSORY' ? ctx.lookup.compulsory_rate
	: 0;
// Act 612 s.2 "upah": basic pay, fixed allowances, leave pay and arrears; (e) no bonus or commission.
// HRD Corp's levy formula is basic pay less unpaid leave plus fixed allowances: leave paid out in money is outside it.
return Math.max(0, ctx.subtotals.WAGE_ARREARS - ctx.encashment) * rate;

