TERMINATION_BENEFIT_PAYMENT.condition:
const r = ctx.entry;
if (ctx.after == null) return false;
const held = first(get(ctx, 'reads.employee_contract', [])) ?? r;
const ground = get(held, 'exit_ground', get(held, 'employee_extension_data.exit_ground', ''));
if (['RESIGNATION', 'RETIREMENT', 'EMPLOYEE_RETIREMENT', 'MISCONDUCT_DISMISSAL', 'TRANSFER', 'TRANSFER_TO_SUBSIDIARY'].includes(ground)) return false;
if (get(held, 'employee_extension_data.misconduct_dismissal', false) === true) return false;
const started = get(held, 'service_started_on', r.effective_range.from);
return calendar_completed_months(started, add_days(r.effective_range.to, 1)) >= ctx.lookup.service_months;

