MINIMUM_WAGE_MONTHLY.validate:
// Minimum Wages Order 2024: a monthly-rated employee earns at least RM1,700 a month.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null || get(rate, 'unit', null) !== 'MONTHLY') return true;
if (['PART_TIME', 'PAYEE'].includes(get(ctx.entry, 'engagement', 'EMPLOYEE'))) return true;
if (['TASK_BASIS', 'DOMESTIC'].includes(get(ctx.entry, 'terms.statutory_work_category', null))) return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
return get(rate, 'amount', 0) >= ctx.lookup.monthly_wage;

MINIMUM_WAGE_HOURLY_PART_TIME.validate:
// A part-time rate is reduced to its hourly equivalent and held to the hourly floor.
const rate = get(ctx.entry, 'terms.rate', null);
if (get(ctx.entry, 'engagement', 'EMPLOYEE') !== 'PART_TIME' || rate == null) return true;
if (get(ctx.entry, 'terms.statutory_work_category', null) === 'DOMESTIC') return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
const unit = get(rate, 'unit', null);
const amount = get(rate, 'amount', 0);
const week = Number(get(ctx.entry, 'terms.normal_hours_per_week', 0));
const day = Number(get(ctx.entry, 'terms.normal_hours_per_day', 0));
const hourly =
  unit === 'MONTHLY' && week > 0 ? (amount * 12) / (ctx.lookup.weeks_per_year * week)
  : unit === 'WEEKLY' && week > 0 ? amount / week
  : unit === 'DAILY' && day > 0 ? amount / day
  : unit === 'HOURLY' ? amount
  : null;
return hourly == null || hourly >= ctx.lookup.hourly_wage;

LABOUR_ORDINANCE_TERRITORY.validate:
// A Sabah or Sarawak worksite belongs to a Labour Ordinance lineage, not the Employment Act.
const region = get(ctx.entry, 'terms.work_region', null);
return region == null || !ctx.lookup.excluded.includes(region);

NORMAL_HOURS_WEEK.validate:
// EA s.60A(1)(d): normal hours are at most 45 a week; shift work averages over three weeks.
const hours = get(ctx.entry, 'terms.normal_hours_per_week', null);
if (hours == null) return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
if (get(facts, 'shift_work', false) === true) return true;
return hours <= ctx.lookup.normal_hours_per_week;

MINIMUM_WAGE_DAILY.validate:
// The daily floor follows the agreed number of working days a week.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null || get(rate, 'unit', null) !== 'DAILY') return true;
if (get(ctx.entry, 'engagement', 'EMPLOYEE') === 'PAYEE') return true;
if (get(ctx.entry, 'terms.statutory_work_category', null) === 'DOMESTIC') return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
const days = Number(get(ctx.entry, 'terms.normal_days_per_week', 6));
const floor =
  days <= 4 ? ctx.lookup.daily_four_day_week
  : days === 5 ? ctx.lookup.daily_five_day_week
  : ctx.lookup.daily_six_day_week;
return get(rate, 'amount', 0) >= floor;

MINIMUM_WAGE_HOURLY.validate:
// An hourly rate is at least RM8.72.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null || get(rate, 'unit', null) !== 'HOURLY') return true;
if (get(ctx.entry, 'engagement', 'EMPLOYEE') === 'PAYEE') return true;
if (get(ctx.entry, 'terms.statutory_work_category', null) === 'DOMESTIC') return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
return get(rate, 'amount', 0) >= ctx.lookup.hourly_wage;

WAGE_PAYMENT_METHOD.validate:
// EA s.25A: wages go through the employee's bank account; another method needs the written request and, for cash or cheque, the Director General's approval.
const method = get(ctx.entry, 'terms.wage_payment_method', null);
if (method == null || ctx.lookup.bank_methods.includes(method)) return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
const approval = get(facts, ctx.lookup.approval_fact, '');
return typeof approval === 'string' && approval !== '';

WAGE_PERIOD.validate:
// EA s.18: the employer's payment schedule may not span more than one month.
const schedule = get(ctx.subject.employer, 'payment_schedule', null);
if (schedule == null || get(schedule, 'frequency', null) !== 'INTEGER_MONTHS') return true;
return Number(get(schedule, 'month_interval', 1)) <= ctx.lookup.maximum_months;

ROSTER_CONTINUOUS_HOURS.validate:
// EA s.60A(1)(a) and proviso (i): five consecutive hours at most between periods of leisure of thirty minutes;
// a shorter break does not end the run. A span is judged on the breaks it records: the roster workbook takes one
// span net of its breaks and records none.
const longest = (span) => {
	const pauses = get(span, 'breaks', []).toSorted((a, b) => elapsed_minutes(span.start, a.start) - elapsed_minutes(span.start, b.start));
	let from = span.start;
	let run = 0;
	let most = 0;
	for (const pause of pauses) {
		run = run + elapsed_minutes(from, pause.start);
		if (elapsed_minutes(pause.start, pause.end) >= ctx.lookup.break_minutes) {
			most = Math.max(most, run);
			run = 0;
		}
		from = pause.end;
	}
	return Math.max(most, run + elapsed_minutes(from, span.end));
};
return get(ctx.entry, 'planned_overtime_intervals', []).every((span) =>
	(get(span, 'breaks', null) == null && get(span, 'break_minutes', null) == null) || longest(span) <= ctx.lookup.elapsed_minutes
);

ROSTER_DAILY_TOTAL.validate:
// EA s.60A(7), s.60C(2): the day's rostered hours, net of unpaid breaks (s.60A(9)) and none on a rest or off day,
// plus its planned overtime, stay within twelve hours.
const shift = ctx.reads.shift_definition.find((s) => s.id === get(ctx.entry, 'shift_definition_id', null));
const variant = get(shift, 'variant', {});
const clock = (t) => Number(t.substring(0, 2)) * 60 + Number(t.substring(3, 5));
const length = (from, to) => (clock(to) - clock(from) + 1440) % 1440;
let rostered = 0;
if (get(variant, 'day_type', 'WORK') === 'WORK') {
	if (get(variant, 'untimed_hours', null) != null) rostered = variant.untimed_hours * 60;
	else if (get(variant, 'start_time', null) != null && get(variant, 'end_time', null) != null) {
		rostered = length(variant.start_time, variant.end_time);
		if (rostered === 0 && variant.ends_next_day === true) rostered = 1440;
		for (const pause of get(variant, 'breaks', [])) if (pause.paid !== true) rostered = rostered - length(pause.start_time, pause.end_time);
	}
}
return rostered + interval_minutes(get(ctx.entry, 'planned_overtime_intervals', [])) <= ctx.lookup.minutes_per_day;

CHILD_EMPLOYMENT.validate:
// Act 350 s.2(2): a child under fifteen needs a permitted employment category.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
if (age_on(born, from) >= ctx.lookup.maximum_age) return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
return ctx.lookup.permitted_kinds.includes(get(facts, 'minor_employment_kind', null));

CHILD_LIGHT_WORK_AGE.validate:
// Act 350 s.2(2A): light family work requires age thirteen or above.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
if (get(facts, 'minor_employment_kind', null) !== ctx.lookup.kind) return true;
return age_on(born, from) >= ctx.lookup.minimum_age;

MINOR_HAZARDOUS_WORK.validate:
// Act 350 s.2(1A)-(1B): hazardous work is closed to children and supervised for young persons.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
const age = age_on(born, from);
if (age >= ctx.lookup.maximum_age) return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
if (get(facts, 'hazardous_work', false) !== true) return true;
if (age < ctx.lookup.child_age) return false;
return get(facts, 'hazardous_work_personal_supervision', false) === true && get(facts, 'hazardous_work_training', false) === true;

MINOR_PROHIBITED_EMPLOYMENT.validate:
// Act 350 s.2(2B): Fifth Schedule employment is closed to every person under eighteen.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
if (age_on(born, from) >= ctx.lookup.maximum_age) return true;
const facts = get(ctx.entry, 'employee_extension_data', {});
return get(facts, 'prohibited_minor_employment', false) !== true;

CONTRACT_CATEGORIES.validate:
// The jurisdiction admits only these contract categories.
const categories = ctx.lookup.categories;
const category = get(ctx.entry, 'terms.statutory_work_category', null);
if (category != null && !categories.statutory_work_category.includes(category)) return false;
const residency = get(ctx.entry, 'terms.residency_status', null);
if (residency != null && !categories.residency_status.includes(residency)) return false;
return true;

SHARED_STRUCTURED_EMPLOYEE_INPUTS.validate:
// The contract's own write checks the work region; this checks the carry limit against the law's minimum.
const carry = get(ctx.entry, 'terms.annual_leave_carry_limit_days', null);
if (carry != null && carry < ctx.lookup.annual_leave_carry_minimum) return false;
return true;

HRD_LIABILITY_EVENT_DATE_REQUIRED.validate:
// PSMB Act 2001: a sealed compulsory or unregistered employer records when its liability began.
if (get(ctx.entry, 'status', 'DRAFT') !== 'SEALED') return true;
const facts = get(ctx.entry, 'entity_extension_data', {});
if (get(facts, 'hrd_scope', '') === 'OUT_OF_SCOPE') return true;
if (!ctx.lookup.liability_classes.includes(get(facts, 'hrd_registration_class', ''))) return true;
return typeof get(facts, 'hrd_registration_liability_on', null) === 'string' && get(facts, 'hrd_registration_liability_on', '') !== '';

BUSINESS_CASE_SUBJECT_AND_REFERENCE.validate:
// These cases must name the actual employment and carry their source document.
if (!ctx.lookup.kinds.includes(get(ctx.entry, 'kind', null))) return true;
return get(ctx.entry, 'employment_id', null) != null && get(ctx.entry, 'evidence_file', null) != null;

BUSINESS_CASE_SIGNED_CONSENT.validate:
// EA s.25A(1): the employee's request is signed, on file, and not after the employer recorded it.
if (get(ctx.entry, 'kind', null) !== ctx.lookup.kind) return true;
const signed = get(ctx.entry, 'inputs.signed_on', null);
if (signed == null || get(ctx.entry, 'evidence_file', null) == null) return false;
return signed <= get(ctx.entry, 'opened_on', '9999-12-31');

DEPARTURE_CASE_ACTUAL_SCHEDULE.validate:
// The departure case records the actual expected date and any later ordered return.
if (get(ctx.entry, 'kind', null) !== ctx.lookup.kind) return true;
const scheduled = get(ctx.entry, 'scheduled_on', null);
if (scheduled == null) return false;
const back = get(ctx.entry, 'inputs.expected_return_on', null);
return back == null || back >= scheduled;

DEATH_NOTICE_ACTUAL_RECEIPT.validate:
// The employer's actual receipt cannot precede the recorded death.
if (get(ctx.entry, 'kind', null) !== ctx.lookup.kind) return true;
const death = get(ctx.entry, 'inputs.death_on', null);
if (death == null) return true;
return death <= get(ctx.entry, 'opened_on', '9999-12-31');

ANNUAL_LEAVE_SERVICE.validate:
const lookup = first(ctx.reads.leave_catalog).lookup;
const contract = first(ctx.reads.employee_contract);
const employment = ctx.subject.employment;
const started = get(contract, 'service_started_on', get(contract, 'effective_range.from'));
const yearOf = (date) => add_months(started, 12 * Math.max(0, Math.floor(calendar_completed_months(started, date) / 12)));
const dates = get(ctx.entry, 'leave_catalog_entry_day', [])
	.map((slot) => String(slot.incurred_on))
	.toSorted();
const years = dates.map(yearOf).filter((year, index, all) => all.indexOf(year) === index);
// EA s.60E(1), second proviso: absent without permission and without reasonable excuse for more than ten per cent of the working days of the twelve months of continuous service in respect of which the leave accrues, the employee is not entitled to it.
const { weeks, max_absent_share, fallback_days_per_week } = lookup.absence_forfeiture;
const absence = ctx.reads.shift_definition.filter((row) => row.variant.day_type === 'ABS').map((row) => row.id);
const absent = ctx.reads.roster_entry.filter((row) => absence.includes(row.shift_definition_id)).map((row) => row.work_date);
const working = weeks * get(employment, 'terms.normal_days_per_week', fallback_days_per_week);
for (const year of years)
	if (absent.filter((date) => date >= year && date < add_months(year, 12)).length > working * max_absent_share)
		throw 'Absent without leave on more than ' + max_absent_share * 100 + ' per cent of the working days of the service year beginning ' + year + ': no annual leave is due for it.';
if (ctx.event.operation !== 'create') return true;
// EA s.60E(3B): leave of absence without pay exceeding thirty days in the aggregate in any twelve months is disregarded in computing the length of service.
const unpaid = ctx.reads.leave_catalog_entry;
const grouped = group_by(ctx.reads.leave_catalog_entry_day, 'leave_entry_id');
const slotsOf = (id) => get(grouped, String(id), []);
const slots = unpaid
	.flatMap((row) => slotsOf(row.id).map((slot) => String(slot.incurred_on)))
	.filter((date) => date < dates.at(0))
	.toSorted();
const reach = 2 * lookup.service_unpaid_leave_ignored_after_days;
let until = '';
let disregarded = 0;
for (let at = 0; at < slots.length; at += 1) {
	if (at + reach < slots.length && slots.at(at + reach) < add_months(slots.at(at), 12)) until = add_months(slots.at(at), 12);
	if (slots.at(at) < until) disregarded += 1;
}
if (disregarded === 0) return true;
const bands = get(employment, 'engagement', '') === 'PART_TIME' ? lookup.part_time_service_bands : lookup.service_bands;
const [opening] = bands;
const due = (months) =>
	months < opening.service_months
		? Math.round((opening.days * months) / opening.service_months)
		: bands.filter((band) => band.service_months <= months).at(-1).days;
const periods = get(first(ctx.reads.employee_balance), 'account.leave.ANNUAL_LEAVE', {});
for (const year of years) {
	const held = Object.hasOwn(periods, 'MY.S.' + year) ? periods['MY.S.' + year] : {};
	const from = dates.find((date) => yearOf(date) === year);
	const net = Math.max(0, calendar_completed_months(add_days(started, Math.floor(disregarded / 2)), from));
	const left = Math.min(get(held, 'entitled', 0), due(net)) + get(held, 'carried', 0) - get(held, 'used', 0);
	if (dates.filter((date) => yearOf(date) === year).length / 2 > left)
		throw 'Unpaid leave of more than ' + lookup.service_unpaid_leave_ignored_after_days + ' days does not count as service for annual leave: ' + left + ' days are left.';
}
return true;

PATERNITY_QUALIFYING_SERVICE.validate:
// EA s.60FA(3)(a): employed by the same employer at least twelve months immediately before the leave commences.
const contract = first(ctx.reads.employee_contract);
const started = get(contract, 'service_started_on', get(contract, 'effective_range.from'));
const from = get(ctx.entry, 'leave_catalog_entry_day', [])
	.map((slot) => String(slot.incurred_on))
	.toSorted()
	.at(0);
const needed = first(ctx.reads.leave_catalog).lookup.eligibility.min_service_months;
if (calendar_completed_months(started, from) < needed)
	throw 'Paternity leave needs ' + needed + ' months with this employer before it begins.';
return true;

PUBLIC_HOLIDAY_IN_LIEU.payout:
// An encashed in-lieu day pays one day at the ordinary rate of pay: the month's wages / 26 (EA 1955 s.60I(1)), to sen.
const day = round(ctx.month_wage / 26, ctx.lookup.minor_unit, 'HALF_UP');
return day * Number(get(ctx.entry, 'quantity', 0));

lookup.entitlement:
// EA First Schedule para 2(5): Part IX does not apply to a domestic employee.
// EA s.37(1)(a)(i): leave for each confinement, and a confinement before this employment is no leave from this employer.
const employment = ctx.subject.employment;
const rule = ctx.lookup.eligibility;
const on = ctx.event.on;
const started = get(employment, 'service_started_on', get(employment, 'effective_range.from'));
if (on < started) return 0;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
const events = get(employment, 'events', []).concat(get(employment, 'family', []).filter((child) => child.relation === 'CHILD' && get(child, 'born_on', null) != null).map((child) => ({ kind: 'CHILD_BIRTH', on: child.born_on })));
const births = events.filter((event) => event.kind.startsWith('CHILD_BIRTH'));
// EA s.37(1)(c), (1)(d)(i): no allowance with five or more surviving natural children at the confinement, whatever their age.
const surviving = births.filter((event) => event.on < on).length - events.filter((event) => event.kind === 'CHILD_DEATH' && event.on < on).length;
// EA s.37(2)(a)(i): ninety days employed in the nine months immediately before the confinement.
const window = add_months(on, -rule.qualifying_window_months);
const served = calendar_distance_days(started > window ? started : window, on);
const allowance = ctx.event.kind === 'CHILD_BIRTH' && surviving <= rule.max_surviving_natural_children && served >= rule.qualifying_service_days;
if (allowance !== ctx.lookup.maternity_allowance) return 0;
// EA s.37(1)(a)(i): one confinement, however many children it brought.
return ctx.lookup.grant_days / births.filter((event) => event.on === on).length;

// EA First Schedule para 2(5): Part IX does not apply to a domestic employee.
// EA s.37(1)(a)(i): leave for each confinement, and a confinement before this employment is no leave from this employer.
const employment = ctx.subject.employment;
const rule = ctx.lookup.eligibility;
const on = ctx.event.on;
const started = get(employment, 'service_started_on', get(employment, 'effective_range.from'));
if (on < started) return 0;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
const events = get(employment, 'events', []).concat(get(employment, 'family', []).filter((child) => child.relation === 'CHILD' && get(child, 'born_on', null) != null).map((child) => ({ kind: 'CHILD_BIRTH', on: child.born_on })));
const births = events.filter((event) => event.kind.startsWith('CHILD_BIRTH'));
// EA s.37(1)(c), (1)(d)(i): no allowance with five or more surviving natural children at the confinement, whatever their age.
const surviving = births.filter((event) => event.on < on).length - events.filter((event) => event.kind === 'CHILD_DEATH' && event.on < on).length;
// EA s.37(2)(a)(i): ninety days employed in the nine months immediately before the confinement.
const window = add_months(on, -rule.qualifying_window_months);
const served = calendar_distance_days(started > window ? started : window, on);
const allowance = ctx.event.kind === 'CHILD_BIRTH' && surviving <= rule.max_surviving_natural_children && served >= rule.qualifying_service_days;
if (allowance !== ctx.lookup.maternity_allowance) return 0;
// EA s.37(1)(a)(i): one confinement, however many children it brought.
return ctx.lookup.grant_days / births.filter((event) => event.on === on).length;

// EA First Schedule para 2(5): s.60F does not apply to a domestic employee.
// EA s.60F(1)(bb): sixty days in the aggregate in each calendar year.
const employment = ctx.subject.employment;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
return ctx.lookup.grant_days;

// EA First Schedule para 2(5): s.60F does not apply to a domestic employee.
// EA s.60F(1)(aa); Employment (Part-Time Employees) Regulations 2010 reg.8(1): the days for the length of service.
const employment = ctx.subject.employment;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
const bands = get(employment, 'engagement', '') === 'PART_TIME' ? ctx.lookup.part_time_service_bands : ctx.lookup.service_bands;
const months = calendar_completed_months(get(employment, 'service_started_on', get(employment, 'effective_range.from')), ctx.as_of);
return get(bands.filter((band) => band.service_months <= months).at(-1), 'days', 0);

// EA First Schedule para 2(5): s.60E does not apply to a domestic employee.
// EA s.60E(1); Employment (Part-Time Employees) Regulations 2010 reg.7(1): the days for the length of service, a share by completed months before the first band.
const employment = ctx.subject.employment;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
const bands = get(employment, 'engagement', '') === 'PART_TIME' ? ctx.lookup.part_time_service_bands : ctx.lookup.service_bands;
const started = get(employment, 'service_started_on', get(employment, 'effective_range.from'));
const months = calendar_completed_months(started, ctx.as_of);
const [opening] = bands;
const exit = get(employment, 'effective_range.to', null);
const exitMonths = exit === null ? null : calendar_completed_months(started, exit);
// EA s.60E(1): completed months, the day itself served; a first-year leaver earns to the exit.
const accruedTo = exit !== null && exitMonths < opening.service_months ? exit : ctx.as_of;
if (months < opening.service_months) return Math.round((opening.days * calendar_completed_months(started, add_days(accruedTo, 1))) / opening.service_months);
const band = bands.filter((b) => b.service_months <= months).at(-1);
// EA s.60E(1) closing words and s.60E(2A): the service year the contract ends in earns in proportion to its completed months; a half day or more is a day.
if (exit === null) return band.days;
const years = Math.floor(months / 12);
if (exitMonths < years * 12 || exitMonths >= (years + 1) * 12) return band.days;
const served = calendar_completed_months(add_months(started, years * 12), add_days(exit, 1));
return Math.round((band.days * served) / 12);

ANNUAL_LEAVE.payout:
const days = Number(get(ctx.entry, 'quantity', 0));
// a day at the ordinary rate of pay: the month's wages / 26 (EA 1955 s.60I(1))
const daily = round(ctx.month_wage / 26, ctx.lookup.minor_unit, 'HALF_UP');
return daily * days;

lookup.entitlement:
// EA First Schedule para 2(5): s.60FA does not apply to a domestic employee.
const employment = ctx.subject.employment;
const on = ctx.event.on;
if (on < get(employment, 'service_started_on', get(employment, 'effective_range.from'))) return 0;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
const births = get(employment, 'events', []).concat(get(employment, 'family', []).filter((child) => child.relation === 'CHILD' && get(child, 'born_on', null) != null).map((child) => ({ kind: 'CHILD_BIRTH', on: child.born_on }))).filter((event) => event.kind === 'CHILD_BIRTH' && event.on <= on);
const confinements = births.map((event) => event.on).filter((date, index, all) => all.indexOf(date) === index);
const record = get(employment, 'employee_extension_data.paternity_confinements', []).find((item) => item.event_id === on);
// EA s.60FA(2): five confinements, irrespective of the number of spouses; a verified record counts those of earlier employers.
if (get(record, 'lifetime_number', confinements.length) > ctx.lookup.eligibility.max_lifetime_confinements) return 0;
// EA s.60FA(3)(b): he has notified the employer of the pregnancy; HR records the finding on the record.
if (get(record, 'notification_requirement_met', true) === false) return 0;
// EA s.60FA(1): seven consecutive days for each confinement, however many children it brought.
return ctx.lookup.grant_days / births.filter((event) => event.on === on).length;

SOCSO_EIS_MONTHLY_CONTRIBUTION.effects:
const r = ctx.entry;
const key = 'MY:SOCSO_EIS_MONTHLY_CONTRIBUTION:' + r.id;
if (get(ctx, 'reads.obligation', []).some((o) => o.occurrence_key === key)) return [];
return [{
	entity_id: r.entity_id,
	title: 'Remit SOCSO, EIS and SKBBK contributions',
	due_on: add_days(r.salary_coverage.to, ctx.lookup.offset_days),
	occurrence_key: key
}];

SKBBK.eligibility:
const employment = ctx.subject.employment;
if (get(employment, 'engagement', '') === 'PAYEE') return false;
if (get(employment, 'employee_extension_data.industrial_training_student', false) === true) return false;
if (get(employment, 'employee_extension_data.statutory.SKBBK.designated_employer', true) === false) return false;
if (ctx.lookup.released_exclusion !== true) return true;
const residency = get(employment, 'terms.residency_status', '');
if (residency !== 'CITIZEN' && residency !== 'PERMANENT_RESIDENT') return true;
return get(employment, 'employee_extension_data.statutory.SKBBK.kind', '') !== 'RELEASED';

SKBBK.employee_amount:
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const charge = (w) => {
if (w <= 0) return 0;
if (w <= ctx.lookup.salary_class_step) return bracket(w, ctx.lookup.bands);
const midpoint =
	w >= ctx.lookup.salary_ceiling
		? ctx.lookup.highest_midpoint
		: round(w, ctx.lookup.hundred_units, 'UP') - ctx.lookup.midpoint_offset;
const total =
	ctx.lookup.round_to_half_step === true
		? round(midpoint * ctx.lookup.total_rate, ctx.lookup.half_step, 'HALF_EVEN')
		: midpoint * ctx.lookup.total_rate;
return total - midpoint * ctx.lookup.own_rate;
};
return charge(Math.min(ctx.subtotals.ORDINARY_WAGES + before('ORDINARY_WAGES'), ctx.lookup.salary_ceiling)) - before('SKBBK.employee');

HRDF.eligibility:
const employment = ctx.subject.employment;
// Act 612 s.2: "pekerja" leaves out a domestic servant and "upah" (f) an apprentice's allowance.
if (['PAYEE', 'PART_TIME', 'APPRENTICE'].includes(get(employment, 'engagement', ''))) return false;
if (get(employment, 'terms.statutory_work_category', '') === 'DOMESTIC') return false;
if (get(employment, 'terms.residency_status', '') !== 'CITIZEN') return false;
const employer = ctx.subject.employer;
if (get(employer, 'entity_extension_data.hrd_scope', '') === 'OUT_OF_SCOPE') return false;
// HRD Corp Circular 01/2026: January to December 2026 wages stay exempt when paid in 2027.
